do $seed$
declare v_author uuid; v_id uuid;
begin
  v_author := coalesce((select author_id from public.guide_authors where guide_id = $t$what-to-do-when-anxiety-hits$t$), (select id from public.profiles where role = 'author' order by created_at asc limit 1));
  if v_author is null then raise notice 'No author account yet: skipped guide what-to-do-when-anxiety-hits'; return; end if;
  select id into v_id from public.content where kind = 'guide' and slug = $t$what-to-do-when-anxiety-hits$t$;
  if v_id is null then
    insert into public.content (author_id, kind, title, description, price, status, tags, slug, created_at)
    values (v_author, 'guide', $t$Що робити, коли накриває тривога$t$, $t$Практичний гайд про те, що відбувається під час тривоги: впізнати свою реакцію, спробувати одну практику заземлення, помітити, що змінилося, і обрати наступний крок.$t$, 0, 'published', array[$t$anxiety$t$, $t$stress$t$]::text[], $t$what-to-do-when-anxiety-hits$t$, $t$2026-10-06$t$::timestamptz)
    returning id into v_id;
  end if;
  insert into public.content_guide_meta (content_id, source, guide_type, category, tag, pages, read_minutes, relevant_if, outcomes, outline, pdf_meta)
  values (v_id, $t$sensoria_structured$t$, $t$practical$t$, $t$Міні-гайди$t$, $t$Новий$t$, 8, 10, array[$t$не знаєте, що робити прямо зараз$t$, $t$відчуваєте сильне напруження в тілі$t$, $t$хочете розібратися, що з вами відбувається$t$, $t$шукаєте конкретний план дій, а не просто «заспокойся»$t$]::text[], array[$t$Розуміння того, як тривога проходить через думки, тіло й поведінку$t$, $t$Одна практика заземлення, яку можна повторити в будь-який момент$t$, $t$Невеликий план на найближчий час$t$]::text[], null, null)
  on conflict (content_id) do update set source = excluded.source, guide_type = excluded.guide_type, category = excluded.category, tag = excluded.tag,
    pages = excluded.pages, read_minutes = excluded.read_minutes, relevant_if = excluded.relevant_if, outcomes = excluded.outcomes, outline = excluded.outline, pdf_meta = excluded.pdf_meta;
  insert into public.content_guide_body (content_id, file_url, blocks)
  values (v_id, null, $t$[{"id":"h-check-in","type":"heading","text":"Спочатку перевірте себе","summary":"Коротка зупинка: що ви відчуваєте просто зараз."},{"id":"t-check-in","type":"rich_text","text":"Зупиніться на хвилину. Нічого не потрібно виправляти чи пояснювати — достатньо помітити, що відбувається."},{"id":"c-now","type":"checklist","completion":"answered","selection":"single","prompt":"Що ви відчуваєте просто зараз?","items":[{"id":"thoughts","label":"Мені важко зупинити думки","note":"Коли думки біжать по колу, це виснажує. Далі ми побачимо, як це влаштовано, і спробуємо повернути увагу до тіла."},{"id":"tension","label":"Відчуваю сильне напруження в тілі","note":"Тіло часто реагує першим. Напруження — це сигнал, і з ним можна працювати через тіло."},{"id":"control","label":"Відчуваю, що втрачаю контроль","note":"Це дуже неприємне відчуття. Воно не означає, що контроль справді втрачено — зараз ми зробимо кілька простих кроків, щоб повернути опору."},{"id":"unclear","label":"Не можу зрозуміти, що саме зі мною","note":"Це нормально — не обов'язково мати назву для стану. Можна почати з того, що просто є."},{"id":"pause","label":"Мені просто потрібна пауза","note":"Пауза — повноцінна відповідь. Цей гайд можна проходити у власному темпі."}]},{"id":"h-what-happens","type":"heading","text":"Що зараз відбувається","summary":"Проста схема того, як тривога проходить через думки, тіло й поведінку."},{"id":"t-what-happens","type":"rich_text","text":"Тривога — це реакція, яка готує нас до можливої складності. Вона буває різної сили, і в більшості випадків має початок і кінець: піднімається, тримається якийсь час і спадає.\n\nЗазвичай це працює як ланцюжок. Одна ланка підсилює наступну, тому вирватися з нього можна в будь-якому місці."},{"id":"f-chain","type":"flow","title":"Як це зазвичай відбувається","steps":[{"label":"Думка","text":"«А якщо піде не так?»"},{"label":"Реакція тіла","text":"серце б'ється швидше, м'язи напружуються"},{"label":"Відчуття","text":"неспокій, тиск, внутрішня «тряска»"},{"label":"Поведінка","text":"перевіряю, уникаю, відволікаюся або завмираю"}],"caption":"Поведінка, у свою чергу, живить нові думки — так ланцюжок замикається."},{"id":"co-not-diagnosis","type":"callout","tone":"note","text":"Це загальна схема для орієнтиру, а не опис вашого стану й не діагноз."},{"id":"h-reaction","type":"heading","text":"Знайдіть свою реакцію","summary":"Що ви зазвичай робите, коли тривога піднімається."},{"id":"c-reactions","type":"checklist","completion":"answered","prompt":"Що ви зазвичай робите, коли тривожитесь? Оберіть усе, що впізнаєте.","items":[{"id":"control-all","label":"починаю все контролювати"},{"id":"search-symptoms","label":"шукаю симптоми в інтернеті"},{"id":"avoid","label":"уникаю ситуації"},{"id":"distract","label":"намагаюся відволіктися"},{"id":"call","label":"телефоную близьким"},{"id":"freeze","label":"завмираю і нічого не роблю"}],"insight":{"one":"Одна з реакцій, яку ви впізнали, — це спосіб впоратися. Часто вона допомагає на мить, але не завжди — надовго.","several":"Ви впізнали кілька реакцій. Це поширено: люди рідко користуються лише однією. Корисно просто помічати, яка з них вмикається першою."}},{"id":"h-try","type":"heading","text":"Спробуйте зараз","summary":"Практика заземлення на 60 секунд."},{"id":"t-try","type":"rich_text","text":"Спершу відзначте, наскільки сильна тривога зараз. Потім — одна коротка практика."},{"id":"s-before","type":"scale","completion":"answered","phase":"before","prompt":"Наскільки сильна тривога зараз?","min":0,"max":10,"lowLabel":"її майже немає","highLabel":"дуже сильна","static":{"prompt":"Наскільки сильна ваша тривога зараз?","instructions":"Оцініть свій стан від 0 до 10 і запишіть число до практики:"}},{"id":"p-grounding","type":"timer_practice","completion":"answered","title":"Заземлення — 60 секунд","intro":"Влаштуйтеся зручно. Можна залишити очі відкритими. Інструкції змінюватимуться самі.","phases":[{"seconds":10,"text":"Сядьте зручно й відчуйте стопи на підлозі та опору під собою."},{"seconds":15,"text":"Повільно вдихніть носом і ще повільніше видихніть. Нехай видих буде довшим за вдих."},{"seconds":20,"text":"Подумки назвіть п'ять речей, які ви бачите просто зараз."},{"seconds":10,"text":"Відчуйте дотики: одяг на шкірі, поверхню під руками."},{"seconds":5,"text":"Зробіть ще один спокійний видих."}],"doneText":"Це все. Побудьте ще мить, перш ніж рухатися далі.","static":{"instructions":"Практика триває приблизно 60 секунд. Можна читати кроки по одному, не поспішаючи."}},{"id":"h-changed","type":"heading","text":"Що змінилося?","summary":"Ще раз оцініть свій стан і порівняйте з початком."},{"id":"t-changed","type":"rich_text","text":"Оцініть ще раз. Іноді стан змінюється, іноді ні — обидва варіанти нормальні, і це інформація, а не оцінка вам чи практиці."},{"id":"s-after","type":"scale","completion":"answered","phase":"after","compareWith":"s-before","prompt":"Наскільки сильна тривога зараз?","min":0,"max":10,"lowLabel":"її майже немає","highLabel":"дуже сильна","static":{"prompt":"Наскільки сильна ваша тривога зараз?","instructions":"Оцініть свій стан від 0 до 10 ще раз і порівняйте з числом, яке записали до практики:"}},{"id":"h-returns","type":"heading","text":"Якщо тривога повертається","summary":"Один наступний крок залежно від того, що заважає найбільше."},{"id":"d-returns","type":"decision_tree","completion":"answered","prompt":"Що зараз найбільше заважає?","branches":[{"id":"thoughts","label":"думки","step":"Запишіть думку одним реченням, а потім додайте до неї: «Я помічаю, що в мене є така думка». Це не прибирає думку, але трохи збільшує відстань до неї."},{"id":"body","label":"тіло","step":"Повторіть практику з розділу 04 — або просто зробіть п'ять повільних видихів, відчуваючи, як опускаються плечі."},{"id":"avoidance","label":"уникання","step":"Оберіть найменший можливий крок у бік того, чого ви уникаєте (наприклад, лише відкрити лист, не відповідаючи), і зробіть тільки його."},{"id":"uncertainty","label":"невизначеність","step":"Розділіть: що з цього залежить від вас сьогодні, а що ні? Оберіть одну дію зі списку «залежить» і відкладіть решту."}]},{"id":"co-support","type":"callout","tone":"care","title":"Коли варто звернутися по підтримку","text":"Якщо тривога тримається тижнями, заважає спати, працювати чи бути з людьми, або вам страшно за власний стан, — це привід поговорити з фахівцем. Звернутися по допомогу — нормальний і розумний крок."},{"id":"h-next","type":"heading","text":"Що може допомогти далі","summary":"Матеріали Sensoria, які добре поєднуються з цим гайдом."},{"id":"r-next","type":"recommendation","prompt":"Якщо захочеться продовжити:","limit":3,"links":{"meditation":"quick-grounding","program":"stress-course"}},{"id":"h-observation","type":"heading","text":"Ваше спостереження","summary":"Приватне місце, щоб записати, що ви помітили."},{"id":"n-observation","type":"reflection","completion":"answered","prompt":"Що ви помітили про себе?","placeholder":"Кілька слів — будь-що, що спало на думку","staticLines":6},{"id":"h-plan","type":"heading","text":"Маленький план","summary":"До трьох невеликих дій на найближчий час."},{"id":"a-plan","type":"action_plan","completion":"answered","prompt":"Що ви готові зробити далі? Оберіть до трьох невеликих дій.","max":3,"items":[{"id":"pause","label":"зробити коротку паузу"},{"id":"repeat","label":"повторити практику"},{"id":"write","label":"записати, що саме викликало тривогу"},{"id":"return","label":"повернутися до цього гайду пізніше"},{"id":"material","label":"відкрити рекомендований матеріал"}]},{"id":"h-closing","type":"heading","text":"Завершення","summary":"Підсумок і що робити, якщо захочеться повернутися."},{"id":"t-closing","type":"rich_text","text":"Ви пройшли цей шлях у власному темпі — це вже достатньо. Тривога не потребує перемоги; її можна навчитися помічати раніше й відпускати спокійніше.\n\nДо цього гайду можна повертатися будь-коли й починати з будь-якого розділу."},{"id":"co-optional-next","type":"callout","tone":"calm","title":"Необов'язковий наступний крок","text":"Якщо хочете, поверніться до практики з розділу 04 завтра в той самий час і просто подивіться, що ви помітите. Якщо не хочеться — теж добре."}]$t$::jsonb)
  on conflict (content_id) do update set file_url = excluded.file_url, blocks = excluded.blocks;
